export const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const MAX_EXPANDED=160*1024*1024;
const ALLOWED_TAGS=['h1','h2','h3','h4','h5','h6','p','div','span','br','hr','a','img','figure','figcaption','blockquote','pre','code','em','strong','b','i','u','s','sub','sup','small','ul','ol','li','dl','dt','dd','table','thead','tbody','tr','td','th','caption','section','article'];
export function sanitize(html){const clean=DOMPurify.sanitize(html,{ALLOWED_TAGS,ALLOWED_ATTR:['id','href','src','alt','title','colspan','rowspan','lang'],FORBID_TAGS:['style','script','iframe','object','embed','form','input','svg','math'],ALLOW_DATA_ATTR:false});const doc=new DOMParser().parseFromString(clean,'text/html');for(const img of doc.querySelectorAll('img')){if(!/^data:image\/(png|jpeg|gif|webp);base64,/i.test(img.getAttribute('src')||''))img.remove();}for(const a of doc.querySelectorAll('a')){const href=a.getAttribute('href')||'';if(/^(?:https?:|mailto:)/i.test(href)){a.target='_blank';a.rel='noopener noreferrer';}else if(/^[a-z][a-z0-9+.-]*:/i.test(href)||href.startsWith('//'))a.removeAttribute('href');}return doc.body.innerHTML;}
export const htmlText=html=>new DOMParser().parseFromString(html,'text/html').body.textContent||'';
function xml(s){const doc=new DOMParser().parseFromString(s,'application/xml');if(doc.querySelector('parsererror'))throw new Error('Cấu trúc sách không hợp lệ.');return doc;}
const elements=(root,name)=>Array.from(root.getElementsByTagNameNS('*',name));
const first=(root,name)=>elements(root,name)[0];
function pathJoin(base,relative){const u=new URL(relative,'https://book.local/'+base);if(u.origin!=='https://book.local')return null;try{return decodeURIComponent(u.pathname.slice(1));}catch{return u.pathname.slice(1);}}
export function checkZip(zip){let total=0;for(const file of Object.values(zip.files)){total+=file._data?.uncompressedSize||0;if(total>MAX_EXPANDED)throw new Error('Sách giải nén quá lớn (giới hạn 160 MB).');}if(Object.keys(zip.files).length>12000)throw new Error('Sách chứa quá nhiều tệp.');}
const rasterMime=path=>({png:'image/png',jpg:'image/jpeg',jpeg:'image/jpeg',gif:'image/gif',webp:'image/webp'}[path.split('.').pop().toLowerCase()]);
async function epub(buffer){const zip=await JSZip.loadAsync(buffer);checkZip(zip);if(zip.file('META-INF/encryption.xml')){const enc=xml(await zip.file('META-INF/encryption.xml').async('string'));const methods=elements(enc,'EncryptionMethod');if(methods.some(x=>!['http://www.idpf.org/2008/embedding','http://ns.adobe.com/pdf/enc#RC'].includes(x.getAttribute('Algorithm'))))throw new Error('EPUB có DRM hoặc mã hóa không được hỗ trợ. Hãy dùng bản không khóa DRM.');}
 const container=zip.file('META-INF/container.xml');if(!container)throw new Error('Không tìm thấy cấu trúc EPUB.');const rootPath=first(xml(await container.async('string')),'rootfile')?.getAttribute('full-path');if(!rootPath||!zip.file(rootPath))throw new Error('Thiếu tệp mô tả EPUB.');const opf=xml(await zip.file(rootPath).async('string'));
 const metadata=first(opf,'metadata');const title=first(metadata||opf,'title')?.textContent?.trim();const author=elements(metadata||opf,'creator').map(x=>x.textContent.trim()).join(', ')||'Chưa rõ tác giả';
 const manifest=new Map(elements(first(opf,'manifest')||opf,'item').map(x=>[x.getAttribute('id'),{href:pathJoin(rootPath,x.getAttribute('href')),type:x.getAttribute('media-type'),properties:x.getAttribute('properties')||''}]));
 const coverId=elements(opf,'meta').find(x=>x.getAttribute('name')==='cover')?.getAttribute('content');const coverItem=Array.from(manifest.values()).find(x=>x.properties.split(/\s+/).includes('cover-image'))||manifest.get(coverId);let cover=null;
 const assets=new Map();let used=0;async function imageData(path){if(assets.has(path))return assets.get(path);const mime=rasterMime(path||'');const file=zip.file(path||'');if(!file||!mime)return '';const bytes=await file.async('uint8array');used+=bytes.length;if(bytes.length>8*1024*1024||used>80*1024*1024)return '';const result=`data:${mime};base64,${await file.async('base64')}`;assets.set(path,result);return result;}
 if(coverItem)cover=await imageData(coverItem.href);
 const chapters=[];const spine=elements(first(opf,'spine')||opf,'itemref').filter(x=>x.getAttribute('linear')!=='no');if(spine.length>2000)throw new Error('EPUB có quá nhiều chương.');
 for(const item of spine){const source=manifest.get(item.getAttribute('idref'));if(!source||!zip.file(source.href)||!/(xhtml|html)/.test(source.type))continue;const sourceText=await zip.file(source.href).async('string');const doc=new DOMParser().parseFromString(sourceText,'text/html');for(const img of doc.querySelectorAll('img')){const path=pathJoin(source.href,img.getAttribute('src')||'');img.setAttribute('src',await imageData(path));}for(const svg of doc.querySelectorAll('svg')){const pic=svg.querySelector('image');if(pic){const path=pathJoin(source.href,pic.getAttribute('href')||pic.getAttribute('xlink:href')||'');const img=doc.createElement('img');img.src=await imageData(path);img.alt='Hình trong sách';svg.replaceWith(img);}}
 const html=sanitize(doc.body.innerHTML);chapters.push({title:doc.querySelector('h1,h2,h3,title')?.textContent?.trim().slice(0,200)||`Chương ${chapters.length+1}`,html,text:htmlText(html),path:source.href});}
 if(!chapters.length)throw new Error('Không tìm thấy nội dung có thể đọc trong EPUB.');let toc=[];
 const nav=Array.from(manifest.values()).find(x=>x.properties.split(/\s+/).includes('nav'));if(nav&&zip.file(nav.href)){const doc=new DOMParser().parseFromString(await zip.file(nav.href).async('string'),'text/html');const navRoot=Array.from(doc.querySelectorAll('nav')).find(n=>(n.getAttribute('epub:type')||'').includes('toc'))||doc.querySelector('nav');toc=Array.from(navRoot?.querySelectorAll('a')||[]).map(a=>{const raw=a.getAttribute('href')||'';return {label:a.textContent.trim(),path:pathJoin(nav.href,raw),anchor:raw.split('#')[1]||''};});}
 if(!toc.length){const ncx=Array.from(manifest.values()).find(x=>x.type==='application/x-dtbncx+xml');if(ncx&&zip.file(ncx.href)){const doc=xml(await zip.file(ncx.href).async('string'));toc=elements(doc,'navPoint').map(n=>{const raw=first(n,'content')?.getAttribute('src')||'';return {label:first(n,'navLabel')?.textContent.trim()||'',path:pathJoin(ncx.href,raw),anchor:raw.split('#')[1]||''};});}}
 toc=toc.map(t=>({...t,index:chapters.findIndex(c=>c.path===t.path)})).filter(t=>t.index>=0&&t.label);return {title,author,cover,chapters,toc};}
function plain(text,markdown=false){const lines=text.replace(/\r\n/g,'\n').split('\n');const chapters=[];let current={title:'Nội dung',lines:[]};for(const line of lines){if((markdown?/^#{1,2}\s+/:/^(?:chương|chapter|phần)\s+[\divxlc]+[\s.:—-]/i).test(line)&&current.lines.join('').trim()){chapters.push(current);current={title:line.replace(/^#+\s*/,''),lines:[]};}current.lines.push(line);}if(current.lines.length)chapters.push(current);return chapters.map((c,i)=>{let html=c.lines.join('\n').split(/\n\s*\n/).filter(Boolean).map(block=>{if(markdown&&/^#{1,6}\s/.test(block)){const n=block.match(/^#+/)[0].length;return `<h${n}>${escapeHTML(block.replace(/^#+\s*/,''))}</h${n}>`;}return `<p>${escapeHTML(block).replace(/\n/g,'<br>')}</p>`;}).join('');if(markdown)html=html.replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/`([^`]+)`/g,'<code>$1</code>');return {title:c.title,html,text:htmlText(html),path:`chapter-${i}`};});}
let pdfModule;
export async function pdfLibrary(){if(!pdfModule){pdfModule=await import('./vendor/pdf.mjs');pdfModule.GlobalWorkerOptions.workerSrc=new URL('./vendor/pdf.worker.mjs',import.meta.url).href;}return pdfModule;}
export async function loadPDF(buffer){const lib=await pdfLibrary();const task=lib.getDocument({data:buffer.slice(0),isEvalSupported:false,useSystemFonts:true,cMapUrl:new URL('./vendor/cmaps/',import.meta.url).href,cMapPacked:true,standardFontDataUrl:new URL('./vendor/standard_fonts/',import.meta.url).href,wasmUrl:new URL('./vendor/wasm/',import.meta.url).href});const doc=await task.promise;if(typeof doc.destroy!=='function')doc.destroy=()=>task.destroy();return doc;}
export async function parseBook(file,onProgress=()=>{}){if(file.size>50*1024*1024)throw new Error('Mỗi tệp tối đa 50 MB.');if(!file.size)throw new Error('Tệp rỗng.');const format=file.name.split('.').pop().toLowerCase();const buffer=await file.arrayBuffer();let result;
 if(format==='epub')result=await epub(buffer);
 else if(format==='pdf'){const pdf=await loadPDF(buffer);try{if(pdf.numPages>2500)throw new Error('PDF vượt giới hạn 2.500 trang.');const meta=await pdf.getMetadata().catch(()=>({info:{}}));const chapters=[];for(let i=1;i<=pdf.numPages;i++){if(i%10===0)onProgress(`Đang đọc PDF: ${i}/${pdf.numPages} trang`);const page=await pdf.getPage(i);const content=await page.getTextContent();let text='';for(const item of content.items){if('str'in item)text+=item.str+(item.hasEOL?'\n':' ');}const html=text.trim()?text.split('\n').map(l=>`<p>${escapeHTML(l)}</p>`).join(''):'<p>Trang này không có lớp văn bản. Chuyển về bố cục PDF để đọc.</p>';chapters.push({title:`Trang ${i}`,html,text:text.trim()?htmlText(html):'',path:`page-${i}`});page.cleanup();}result={title:meta.info?.Title,author:meta.info?.Author||'Chưa rõ tác giả',chapters,toc:[]};}finally{await pdf.destroy();}}
 else if(['txt','md','markdown'].includes(format)){const text=new TextDecoder('utf-8').decode(buffer);result={chapters:plain(text,format!=='txt')};}
 else if(['html','htm'].includes(format)){const doc=new DOMParser().parseFromString(new TextDecoder().decode(buffer),'text/html');const html=sanitize(doc.body.innerHTML);result={title:doc.title||doc.querySelector('h1')?.textContent,chapters:[{title:'Nội dung',html,text:htmlText(html),path:'content'}]};}
 else if(format==='fb2'){const doc=xml(new TextDecoder().decode(buffer));const info=first(doc,'title-info');const bodies=elements(doc,'body');const images=new Map(elements(doc,'binary').filter(x=>/^image\/(jpeg|png|gif|webp)$/.test(x.getAttribute('content-type'))).map(x=>[x.getAttribute('id'),`data:${x.getAttribute('content-type')};base64,${x.textContent.replace(/\s/g,'')}`]));function convert(n){if(n.nodeType===3)return escapeHTML(n.textContent);if(n.nodeType!==1)return '';const tag=n.localName;if(tag==='image'){const href=n.getAttribute('l:href')||n.getAttribute('xlink:href')||n.getAttribute('href')||'';return `<img src="${images.get(href.slice(1))||''}" alt="">`;}const map={title:'h2',subtitle:'h3',p:'p',section:'section',emphasis:'em',strong:'strong',poem:'blockquote',stanza:'div',v:'p',epigraph:'blockquote','empty-line':'br'};const dest=map[tag]||'div';return `<${dest}>${Array.from(n.childNodes).map(convert).join('')}</${dest}>`;}
 const mainBody=bodies.find(b=>!b.getAttribute('name'))||bodies[0];if(!mainBody)throw new Error('Không có nội dung FB2.');const sections=Array.from(mainBody.children).filter(x=>x.localName==='section');result={title:first(info||doc,'book-title')?.textContent,author:elements(info||doc,'author').map(a=>a.textContent.trim().replace(/\s+/g,' ')).join(', '),chapters:(sections.length?sections:[mainBody]).map((s,i)=>{const html=sanitize(convert(s));return {title:first(s,'title')?.textContent.trim()||`Phần ${i+1}`,html,text:htmlText(html),path:`section-${i}`};})};}
 else throw new Error('Định dạng chưa được hỗ trợ. Dùng EPUB, PDF, TXT, MD, HTML hoặc FB2.');
 if(!result.chapters?.length)throw new Error('Không tìm thấy nội dung sách.');const id=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',buffer))).map(x=>x.toString(16).padStart(2,'0')).join('');return {book:{id,title:(result.title||file.name.replace(/\.[^.]+$/,'')).slice(0,300),author:(result.author||'Chưa rõ tác giả').slice(0,300),format:format.toUpperCase(),filename:file.name,size:file.size,cover:result.cover||null,added:Date.now(),lastRead:0,progress:0,chapter:0,offset:0,status:'unread',favorite:false,collection:'',bookmarks:[],notes:[],chapterCount:result.chapters.length},content:{chapters:result.chapters,toc:result.toc?.length?result.toc:result.chapters.map((c,index)=>({label:c.title,index,anchor:''})),original:new Blob([buffer],{type:file.type||'application/octet-stream'})}};}
